interface SplitStrategy {
    Map<String, Long> computeShares(long totalAmount,
                                     List<String> participants,
                                     Object params);
}

class EqualSplit implements SplitStrategy {
    @Override
    public Map<String, Long> computeShares(long total,
                                            List<String> participants,
                                            Object params) {
        int n = participants.size();
        if (n == 0) throw new IllegalArgumentException("no participants");

        long baseShare = total / n;
        long remainder = total - (baseShare * n);  // cents unaccounted for

        Map<String, Long> shares = new LinkedHashMap<>();
        for (int i = 0; i < n; i++) {
            // First `remainder` users pay 1 cent extra — no money lost
            long share = baseShare + (i < remainder ? 1 : 0);
            shares.put(participants.get(i), share);
        }
        return shares;
    }
}

class ExactSplit implements SplitStrategy {
    @Override
    @SuppressWarnings("unchecked")
    public Map<String, Long> computeShares(long total,
                                            List<String> participants,
                                            Object params) {
        Map<String, Long> shares = (Map<String, Long>) params;
        long sum = shares.values().stream().mapToLong(Long::longValue).sum();
        if (sum != total)
            throw new InvalidSplitException(
                "Exact split sum " + sum + " != total " + total);
        // Validate all participants are in shares map
        for (String uid : participants) {
            if (!shares.containsKey(uid))
                throw new InvalidSplitException("Missing share for " + uid);
        }
        return shares;
    }
}

class PercentageSplit implements SplitStrategy {
    @Override
    @SuppressWarnings("unchecked")
    public Map<String, Long> computeShares(long total,
                                            List<String> participants,
                                            Object params) {
        Map<String, Double> percents = (Map<String, Double>) params;
        double sumPct = percents.values().stream().mapToDouble(Double::doubleValue).sum();
        if (Math.abs(sumPct - 100.0) > 0.001)
            throw new InvalidSplitException(
                "Percentages must sum to 100, got " + sumPct);

        Map<String, Long> shares = new LinkedHashMap<>();
        long allocated = 0;
        List<String> pList = new ArrayList<>(percents.keySet());
        for (int i = 0; i < pList.size() - 1; i++) {
            String uid = pList.get(i);
            long share = Math.round(total * percents.get(uid) / 100.0);
            shares.put(uid, share);
            allocated += share;
        }
        // Last participant gets the remainder — absorbs rounding error
        shares.put(pList.get(pList.size() - 1), total - allocated);
        return shares;
    }
}

class BalanceSheet {
    // balances[owedBy][owedTo] = amount
    // If A owes B $10: balances[A][B] = 10, balances[B][A] = -10 (kept in sync)
    private final ConcurrentHashMap<String, ConcurrentHashMap<String, Long>>
        balances = new ConcurrentHashMap<>();
    private final Object lock = new Object();

    // ── Record an expense — paidBy paid for all participants ──
    public void recordExpense(String paidBy, Map<String, Long> shares) {
        synchronized (lock) {
            for (Map.Entry<String, Long> e : shares.entrySet()) {
                String participant = e.getKey();
                long share = e.getValue();
                if (participant.equals(paidBy)) continue;  // skip self
                // participant owes paidBy `share`
                updateBalance(participant, paidBy, share);
            }
        }
    }

    public void recordSettlement(String from, String to, long amount) {
        synchronized (lock) {
            // `from` pays `to` → reduces what `from` owes `to` (or increases what `to` owes `from`)
            updateBalance(from, to, -amount);
        }
    }

    // Internal: `debtor` owes `creditor` `amount` more
    private void updateBalance(String debtor, String creditor, long amount) {
        balances.computeIfAbsent(debtor, k -> new ConcurrentHashMap<>())
                .merge(creditor, amount, Long::sum);
        balances.computeIfAbsent(creditor, k -> new ConcurrentHashMap<>())
                .merge(debtor, -amount, Long::sum);
    }

    // Net: positive = `u1` owes `u2`, negative = `u2` owes `u1`
    public long getBalance(String u1, String u2) {
        return balances.getOrDefault(u1, new ConcurrentHashMap<>())
                       .getOrDefault(u2, 0L);
    }

    // Per-user net: sum across all counterparties
    public Map<String, Long> getNetBalances(Set<String> users) {
        Map<String, Long> net = new HashMap<>();
        for (String u : users) {
            long sum = balances.getOrDefault(u, new ConcurrentHashMap<>())
                               .values().stream()
                               .mapToLong(Long::longValue).sum();
            // sum > 0 → user owes money (positive debt)
            // sum < 0 → user is owed money (creditor)
            // We invert so positive = creditor, for standard 'net balance'
            net.put(u, -sum);
        }
        return net;
    }

    // ── Debt Simplification — Greedy O(N log N) ──
    // Compute net per user; pair biggest creditor with biggest debtor until all zero.
    public List<Settlement> simplifyDebts(Set<String> users) {
        Map<String, Long> net = getNetBalances(users);

        // Two priority queues: creditors (positive) and debtors (negative)
        PriorityQueue<Map.Entry<String, Long>> creditors =
            new PriorityQueue<>((a, b) -> Long.compare(b.getValue(), a.getValue()));
        PriorityQueue<Map.Entry<String, Long>> debtors =
            new PriorityQueue<>(Comparator.comparingLong(Map.Entry::getValue));

        for (Map.Entry<String, Long> e : net.entrySet()) {
            if (e.getValue() > 0) creditors.offer(new AbstractMap.SimpleEntry<>(e));
            else if (e.getValue() < 0) debtors.offer(new AbstractMap.SimpleEntry<>(e));
        }

        List<Settlement> result = new ArrayList<>();
        while (!creditors.isEmpty() && !debtors.isEmpty()) {
            Map.Entry<String, Long> c = creditors.poll();
            Map.Entry<String, Long> d = debtors.poll();

            long amount = Math.min(c.getValue(), -d.getValue());
            result.add(new Settlement(d.getKey(), c.getKey(), amount));

            long cRemaining = c.getValue() - amount;
            long dRemaining = d.getValue() + amount;

            if (cRemaining > 0)
                creditors.offer(new AbstractMap.SimpleEntry<>(c.getKey(), cRemaining));
            if (dRemaining < 0)
                debtors.offer(new AbstractMap.SimpleEntry<>(d.getKey(), dRemaining));
        }
        return result;
    }
}

