class SplitwiseService {
    private final Map<String, User> users = new ConcurrentHashMap<>();
    private final Map<String, Group> groups = new ConcurrentHashMap<>();
    private final List<Expense> expenseHistory =
        Collections.synchronizedList(new ArrayList<>());
    private final BalanceSheet balanceSheet = new BalanceSheet();

    // ── addExpense ───────────────────────
    public String addExpense(String paidByUserId, long amount,
                              List<String> participantIds,
                              SplitType splitType, Object params) {
        if (amount <= 0)
            throw new IllegalArgumentException("Amount must be positive");
        if (!users.containsKey(paidByUserId))
            throw new UserNotFoundException(paidByUserId);
        for (String pid : participantIds) {
            if (!users.containsKey(pid))
                throw new UserNotFoundException(pid);
        }

        SplitStrategy strategy = switch (splitType) {
            case EQUAL      -> new EqualSplit();
            case EXACT      -> new ExactSplit();
            case PERCENTAGE -> new PercentageSplit();
        };

        Map<String, Long> shares =
            strategy.computeShares(amount, participantIds, params);

        Expense expense = new Expense(UUID.randomUUID().toString(),
            paidByUserId, amount, shares, splitType, System.currentTimeMillis());
        expenseHistory.add(expense);

        balanceSheet.recordExpense(paidByUserId, shares);
        return expense.expenseId();
    }

    public void settleUp(String fromUser, String toUser, long amount) {
        if (amount <= 0)
            throw new IllegalArgumentException("Amount must be positive");
        balanceSheet.recordSettlement(fromUser, toUser, amount);
    }

    public long getBalance(String u1, String u2) {
        return balanceSheet.getBalance(u1, u2);
    }

    public List<Settlement> simplifyGroupDebts(String groupId) {
        Group g = groups.get(groupId);
        if (g == null) throw new IllegalArgumentException("Unknown group");
        return balanceSheet.simplifyDebts(g.memberIds());
    }
}

